package br.com.admeclesial.application.financeiro; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*; @Service public class TransferenciaFinanceiraApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final TransferenciaFinanceiraRepository repo; final ContaFinanceiraRepository contas; final MovimentacaoFinanceiraRepository movimentos; public TransferenciaFinanceiraApplicationService(TransferenciaFinanceiraRepository r,ContaFinanceiraRepository c,MovimentacaoFinanceiraRepository m){repo=r;contas=c;movimentos=m;} @Transactional public TransferenciaFinanceira criar(TransferenciaFinanceiraRequest r){var origem=contas.findByUuid(r.contaOrigemUuid()).orElseThrow(()->new IllegalArgumentException("Conta de origem não encontrada."));var destino=contas.findByUuid(r.contaDestinoUuid()).orElseThrow(()->new IllegalArgumentException("Conta de destino não encontrada."));if(seguranca!=null)seguranca.validarAcessoId(origem.getOrganizacaoEclesialId());if(seguranca!=null)seguranca.validarAcessoId(destino.getOrganizacaoEclesialId());if(!origem.getAtivo()||!destino.getAtivo())throw new IllegalArgumentException("As contas devem estar ativas.");if(origem.getId().equals(destino.getId()))throw new IllegalArgumentException("Contas de origem e destino devem ser diferentes.");if(!origem.getOrganizacaoEclesialId().equals(destino.getOrganizacaoEclesialId()))throw new IllegalArgumentException("As contas devem pertencer à mesma organização.");var mo=new MovimentacaoFinanceira();mo.setContaFinanceiraId(origem.getId());mo.setTipo(TipoMovimentacaoFinanceira.TRANSFERENCIA);mo.setValor(r.valor());mo.setDataMovimentacao(r.dataTransferencia());mo.setDescricao("Transferência para " + destino.getUuid());mo.setStatus(StatusMovimentacaoFinanceira.CONFIRMADA);mo=movimentos.save(mo);var md=new MovimentacaoFinanceira();md.setContaFinanceiraId(destino.getId());md.setTipo(TipoMovimentacaoFinanceira.TRANSFERENCIA);md.setValor(r.valor());md.setDataMovimentacao(r.dataTransferencia());md.setDescricao("Transferência de " + origem.getUuid());md.setStatus(StatusMovimentacaoFinanceira.CONFIRMADA);md=movimentos.save(md);var t=new TransferenciaFinanceira();t.setContaOrigemId(origem.getId());t.setContaDestinoId(destino.getId());t.setMovimentacaoOrigemId(mo.getId());t.setMovimentacaoDestinoId(md.getId());t.setValor(r.valor());t.setDataTransferencia(r.dataTransferencia());t.setObservacao(r.observacao());return repo.save(t);} @Transactional(readOnly=true) public List<TransferenciaFinanceira> listar(){return repo.findAll().stream().filter(t->{var c=contas.findById(t.getContaOrigemId()).orElse(null);if(c==null)return false;try{if(seguranca!=null)seguranca.validarAcessoId(c.getOrganizacaoEclesialId());return true;}catch(org.springframework.security.access.AccessDeniedException ex){return false;}}).toList();}}
